package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigMatrixImpl_operate_TriageGen1Test {

    @Test
    public void testOperate_Success() {
        // Setup a 2x3 matrix
        // [ 1, 2, 3 ]
        // [ 4, 5, 6 ]
        BigDecimal[][] data = {
            {BigDecimal.ONE, BigDecimal.valueOf(2), BigDecimal.valueOf(3)},
            {BigDecimal.valueOf(4), BigDecimal.valueOf(5), BigDecimal.valueOf(6)}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector [1, 0, 2]
        // Expected Result:
        // Row 0: (1*1) + (2*0) + (3*2) = 7
        // Row 1: (4*1) + (5*0) + (6*2) = 16
        BigDecimal[] v = {BigDecimal.ONE, BigDecimal.ZERO, BigDecimal.valueOf(2)};
        BigDecimal[] expected = {BigDecimal.valueOf(7), BigDecimal.valueOf(16)};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_WrongLength_ThrowsException() {
        // Setup a 2x2 matrix
        BigMatrixImpl matrix = new BigMatrixImpl(2, 2);

        // Vector of length 3 instead of 2
        BigDecimal[] v = {BigDecimal.ONE, BigDecimal.ONE, BigDecimal.ONE};

        try {
            matrix.operate(v);
            Assert.fail("Expected IllegalArgumentException to be thrown");
        } catch (IllegalArgumentException e) {
            Assert.assertEquals("vector has wrong length", e.getMessage());
        }
    }

    @Test
    public void testOperate_SingleElement() {
        // Setup a 1x1 matrix
        BigDecimal[][] data = {{BigDecimal.valueOf(5)}};
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {BigDecimal.valueOf(2)};
        BigDecimal[] expected = {BigDecimal.valueOf(10)};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_WithZeroValues() {
        // Setup a 2x2 matrix
        BigDecimal[][] data = {
            {BigDecimal.ZERO, BigDecimal.TEN},
            {BigDecimal.TEN, BigDecimal.ZERO}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {BigDecimal.TEN, BigDecimal.TEN};
        // Row 0: 0*10 + 10*10 = 100
        // Row 1: 10*10 + 0*10 = 100
        BigDecimal[] expected = {BigDecimal.valueOf(100), BigDecimal.valueOf(100)};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }
}
